mapper.select:
SELECT a.id, a.student_id, a.offering_id, a.attend_date, a.attend_type, a.remark, a.recorder_id, a.create_time, s.student_no AS studentNo, s.name AS studentName, c.class_name AS className, cc.course_name AS courseName, CASE a.attend_type WHEN 1 THEN '出勤' WHEN 2 THEN '迟到' WHEN 3 THEN '早退' WHEN 4 THEN '缺勤' WHEN 5 THEN '请假' ELSE '未知' END AS attendTypeText, t.name AS recorderName FROM att_attendance a INNER JOIN stu_student s ON s.id = a.student_id AND s.deleted = 0 LEFT JOIN base_class c ON c.id = s.class_id AND c.deleted = 0 LEFT JOIN course_offering o ON o.id = a.offering_id AND o.deleted = 0 LEFT JOIN course_course cc ON cc.id = o.course_id AND cc.deleted = 0 LEFT JOIN tea_teacher t ON t.id = a.recorder_id WHERE 1 = 1
AND a.student_id = #{scope.studentId}
AND s.class_id IN #{cid}
AND 1 = 0
AND (s.student_no LIKE CONCAT('%', #{q.keyword}, '%') OR s.name LIKE CONCAT('%', #{q.keyword}, '%') OR cc.course_name LIKE CONCAT('%', #{q.keyword}, '%'))
AND s.class_id = #{q.classId} AND a.offering_id = #{q.offeringId} AND a.student_id = #{q.studentId} AND a.attend_type = #{q.attendType} AND a.attend_date >= #{q.startDate} AND a.attend_date <= #{q.endDate} ORDER BY a.attend_date DESC, s.student_no ASC
